    adj = {}
    for a, b in edges:
        if not isinstance(a, str) or not isinstance(b, str):
            continue
        adj.setdefault(a, []).append(b)

    # Normal shortest path case
    if source != target:
        visited = {source: 0}
        q = deque([source])
        while q:
            node = q.popleft()
            if node == target:
                return visited[node]
            for nxt in adj.get(node, []):
                if nxt not in visited:
                    visited[nxt] = visited[node] + 1
                    q.append(nxt)
        return -1  # unreachable

    # Self-transfer case: need a positive-length round trip back to the same node
    # Use BFS and stop when we encounter the start node again via an edge
    visited = {source: 0}
    q = deque([source])
    while q:
        node = q.popleft()
        for nxt in adj.get(node, []):
            if nxt == source:
                # found a round trip: distance from source to node plus the returning edge
                return visited[node] + 1
            if nxt not in visited:
                visited[nxt] = visited[node] + 1
                q.append(nxt)
    return -1  # no valid round trip exists
